const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const { promisify } = require('util');

const STORAGE_DIR = '/var/secure-storage';
const ALGORITHM = 'aes-256-gcm';
const KEY_LENGTH = 32;
const IV_LENGTH = 12;
const TAG_LENGTH = 16;

class SecureFileProcessor {
  constructor(masterKey) {
    this.masterKey = Buffer.from(masterKey, 'hex');
    this.fileRegistry = new Map();
    this.lockTable = new Map();
  }

  _derivePath(userId, filename) {
    const hash = crypto.createHmac('sha256', this.masterKey)
      .update(`${userId}/${filename}`)
      .digest('hex');
    return path.join(STORAGE_DIR, hash.slice(0, 2), hash.slice(2, 4), hash);
  }

  _deriveKey(userId, filename) {
    return crypto.pbkdf2Sync(
      this.masterKey,
      Buffer.from(`${userId}:${filename}`, 'utf8'),
      100000,
      KEY_LENGTH,
      'sha512'
    );
  }

  async acquireLock(resourceId) {
    const lockEntry = this.lockTable.get(resourceId);
    if (lockEntry && lockEntry.held) {
      return new Promise((resolve) => {
        lockEntry.waiters.push(resolve);
      });
    }
    this.lockTable.set(resourceId, { held: true, waiters: [], owner: null });
    return true;
  }

  releaseLock(resourceId) {
    const lockEntry = this.lockTable.get(resourceId);
    if (!lockEntry) return;
    if (lockEntry.waiters.length > 0) {
      const next = lockEntry.waiters.shift();
      next(true);
    } else {
      lockEntry.held = false;
    }
  }

  async encryptAndStore(userId, filename, plaintext) {
    const sanitizedFilename = path.basename(filename);
    const filePath = this._derivePath(userId, sanitizedFilename);
    const fileKey = this._deriveKey(userId, sanitizedFilename);
    const resourceId = `${userId}:${sanitizedFilename}`;

    await this.acquireLock(resourceId);
    try {
      const iv = crypto.randomBytes(IV_LENGTH);
      const cipher = crypto.createCipheriv(ALGORITHM, fileKey, iv);
      cipher.setAAD(Buffer.from(resourceId, 'utf8'));

      const encrypted = Buffer.concat([
        cipher.update(plaintext, 'utf8'),
        cipher.final()
      ]);
      const tag = cipher.getAuthTag();

      const envelope = Buffer.concat([
        iv,
        tag,
        encrypted
      ]);

      await fs.promises.mkdir(path.dirname(filePath), { recursive: true });
      await fs.promises.writeFile(filePath, envelope);

      this.fileRegistry.set(resourceId, {
        path: filePath,
        size: envelope.length,
        created: Date.now()
      });

      return { success: true, resourceId };
    } finally {
      this.releaseLock(resourceId);
    }
  }

  async readAndDecrypt(userId, filename) {
    const sanitizedFilename = path.basename(filename);
    const filePath = this._derivePath(userId, sanitizedFilename);
    const fileKey = this._deriveKey(userId, sanitizedFilename);
    const resourceId = `${userId}:${sanitizedFilename}`;

    const registryEntry = this.fileRegistry.get(resourceId);
    if (!registryEntry) {
      throw new Error('File not found in registry');
    }

    await this.acquireLock(resourceId);
    try {
      const envelope = await fs.promises.readFile(filePath);

      const iv = envelope.slice(0, IV_LENGTH);
      const tag = envelope.slice(IV_LENGTH, IV_LENGTH + TAG_LENGTH);
      const ciphertext = envelope.slice(IV_LENGTH + TAG_LENGTH);

      const decipher = crypto.createDecipheriv(ALGORITHM, fileKey, iv);
      decipher.setAAD(Buffer.from(resourceId, 'utf8'));
      decipher.setAuthTag(tag);

      const decrypted = Buffer.concat([
        decipher.update(ciphertext),
        decipher.final()
      ]);

      return decrypted.toString('utf8');
    } finally {
      this.releaseLock(resourceId);
    }
  }

  async deleteFile(userId, filename) {
    const sanitizedFilename = path.basename(filename);
    const resourceId = `${userId}:${sanitizedFilename}`;

    const registryEntry = this.fileRegistry.get(resourceId);
    if (!registryEntry) {
      throw new Error('File not found in registry');
    }

    await this.acquireLock(resourceId);
    try {
      this.fileRegistry.delete(resourceId);
      await fs.promises.unlink(registryEntry.path);
      return { success: true };
    } finally {
      this.releaseLock(resourceId);
    }
  }

  async replaceFile(userId, filename, newContent) {
    const sanitizedFilename = path.basename(filename);
    const resourceId = `${userId}:${sanitizedFilename}`;

    const registryEntry = this.fileRegistry.get(resourceId);
    if (!registryEntry) {
      throw new Error('File not found in registry');
    }

    const currentContent = await this.readAndDecrypt(userId, sanitizedFilename);

    if (currentContent.length === 0) {
      throw new Error('Cannot replace empty file');
    }

    return await this.encryptAndStore(userId, sanitizedFilename, newContent);
  }
}

module.exports = SecureFileProcessor;
